// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(address(this), amount);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "receive failed");
        if (address(c).balance > 0) {
            assertTrue(c.depositsCount() > 0);
        } else {
            assertTrue(c.depositsCount() == 0);
        }
    }
}
